var searchInput = document.querySelector(".Q_SearchText");
var resultsContainer = document.querySelector(".C_SearchResults");
var title = document.querySelector(".Q_Header2Text");
var queryTitle = document.querySelector(".Q_Header2Query");
var params = new URLSearchParams(window.location.search);
var queryFromUrl = params.get("q") || "";
function normalizeText(text) {
  return String(text || "").toLowerCase().trim();
}
function getSearchResults(query) {
  var normalizedQuery = normalizeText(query);
  if (!normalizedQuery) {
    return [];
  }
  return searchItems.filter(function (item) {
    var searchableText = normalizeText("".concat(item.title, " ").concat(item.description, " ").concat(item.type));
    return searchableText.includes(normalizedQuery);
  });
}
function createSearchResult(result) {
  var link = document.createElement("a");
  link.classList.add("M_SearchResult");
  link.href = result.url;
  link.innerHTML = "\n    <div class=\"A_H3\">\n      <h3 class=\"Q_Header3Text\">".concat(result.title, "</h3>\n    </div>\n\n    <p class=\"A_TextBlock\">").concat(result.description || "", "</p>\n\n    <p class=\"A_SearchResultType\">").concat(result.type, "</p>\n  ");
  return link;
}
function updateTitle(query) {
  if (!title) return;
  if (!query) {
    title.textContent = "Что потеряли?";
    title.dataset.text = "Что потеряли?";
    if (queryTitle) {
      queryTitle.textContent = "";
      queryTitle.dataset.text = "";
    }
    return;
  }
  title.textContent = "Что нашлось по запросу";
  title.dataset.text = "Что нашлось по запросу";
  if (queryTitle) {
    queryTitle.textContent = "\xAB".concat(query, "\xBB");
    queryTitle.dataset.text = "\xAB".concat(query, "\xBB");
  }
}
function renderResults(query) {
  if (!resultsContainer) return;
  var normalizedQuery = query.trim();
  var results = getSearchResults(normalizedQuery);
  resultsContainer.innerHTML = "";
  updateTitle(normalizedQuery);
  if (!normalizedQuery) {
    resultsContainer.innerHTML = "\n      <p class=\"A_TextBlock\">\u0412\u0432\u0435\u0434\u0438\u0442\u0435 \u0437\u0430\u043F\u0440\u043E\u0441 \u0432 \u043F\u043E\u0438\u0441\u043A\u043E\u0432\u0443\u044E \u0441\u0442\u0440\u043E\u043A\u0443</p>\n    ";
    return;
  }
  if (results.length === 0) {
    resultsContainer.innerHTML = "\n      <p class=\"A_TextBlock\">\u041D\u0438\u0447\u0435\u0433\u043E \u043D\u0435 \u043D\u0430\u0448\u043B\u043E\u0441\u044C :(</p>\n    ";
    return;
  }
  results.forEach(function (result) {
    resultsContainer.appendChild(createSearchResult(result));
  });
}
function goToSearchPage(query) {
  var normalizedQuery = query.trim();
  if (!normalizedQuery) return;
  window.location.href = "https://mememedia.adc.ac/search.html?q=".concat(encodeURIComponent(normalizedQuery));
}
function initSearchPage() {
  if (searchInput) {
    searchInput.value = queryFromUrl;
    searchInput.addEventListener("keydown", function (event) {
      if (event.key !== "Enter") return;
      goToSearchPage(searchInput.value);
    });
  }
  renderResults(queryFromUrl);
}
document.addEventListener("DOMContentLoaded", initSearchPage);
